package com.echovault.servlet;
import com.echovault.dao.UserDAO;import com.echovault.util.Flash;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet("/login") public class LoginServlet extends HttpServlet {protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{try{int id=new UserDAO().authenticate(q.getParameter("email"),q.getParameter("password"));if(id<0){Flash.set(q,"error","Email or password is incorrect.");s.sendRedirect("login.jsp");return;}HttpSession old=q.getSession(false);if(old!=null)old.invalidate();HttpSession h=q.getSession(true);h.setAttribute("userId",id);h.setAttribute("userEmail",q.getParameter("email").trim().toLowerCase());h.setAttribute("userName",new UserDAO().name(id));s.sendRedirect("dashboard");}catch(Exception e){getServletContext().log("Login failed",e);Flash.set(q,"error","Unable to sign in. Check the database connection.");s.sendRedirect("login.jsp");}}}